import { useState } from "react";
import "../styles/login-ui.css";

export default function RegisterPage({ onBack }) {
  const [form, setForm] = useState({
    username: "",
    email: "",
    college: "",
    password: ""
  });

  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const [serverError, setServerError] = useState("");

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setErrors({ ...errors, [e.target.name]: "" });
  };

  const validate = () => {
    const newErrors = {};

    if (!form.username.trim()) newErrors.username = "Username is required";

    if (!form.email.trim())
      newErrors.email = "Email is required";
    else if (!/\S+@\S+\.\S+/.test(form.email))
      newErrors.email = "Invalid email format";

    if (!form.college.trim()) newErrors.college = "College name is required";

    if (!form.password)
      newErrors.password = "Password is required";
    else if (form.password.length < 6)
      newErrors.password = "Minimum 6 characters";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const register = async () => {
    setServerError("");

    if (!validate()) return;

    setLoading(true);

    try {
      const res = await fetch("http://localhost:8000/api/register/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form)
      });

      const data = await res.json();

      if (!res.ok) {
        setServerError(data.error || "Registration failed");
      } else {
        alert("Registration successful. Please login.");
        onBack();
      }

    } catch (err) {
      setServerError("Cannot connect to server");
    }

    setLoading(false);
  };

  return (
    <div className="login-container">
      <div className="login-page">
        <h2>Create Account</h2>
        <p className="sub-text">Register to use Digital Canteen</p>

        <div className="form-group">
          <input
            name="username"
            placeholder="Username"
            value={form.username}
            onChange={handleChange}
          />
          {errors.username && <span className="field-error">{errors.username}</span>}
        </div>

        <div className="form-group">
          <input
            name="email"
            placeholder="Email address"
            value={form.email}
            onChange={handleChange}
          />
          {errors.email && <span className="field-error">{errors.email}</span>}
        </div>

        <div className="form-group">
          <input
            name="college"
            placeholder="College name"
            value={form.college}
            onChange={handleChange}
          />
          {errors.college && <span className="field-error">{errors.college}</span>}
        </div>

        <div className="form-group">
          <input
            type="password"
            name="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
          />
          {errors.password && <span className="field-error">{errors.password}</span>}
        </div>

        {serverError && <div className="server-error">{serverError}</div>}

        <button onClick={register} disabled={loading}>
          {loading ? "Registering..." : "Register"}
        </button>

        <button className="secondary-btn" onClick={onBack}>
          Back to Login
        </button>
      </div>

      <div className="login-slider register-slider">
        <div className="slider-overlay">
          <h3>Join Digital Canteen</h3>
          <p>Easy • Fast • Smart food ordering</p>
        </div>
      </div>
    </div>
  );
}
